-- Canada Electrician occupation profile.
-- Exact NOC 2021 72200 Electricians (except industrial and power system).

insert into public.country_occupation_profiles (profile_key,country_code,canonical_career_id,official_title,official_code_system,official_code_version,official_unit_group_code,currency,registration_required,registration_authority,registration_url,publication_status,source_checked_at,updated_at)
values ('CA:electrician','CA','electrician','Electricians (except industrial and power system)','NOC','2021 Version 1.0','72200','CAD',true,'Provincial and territorial electrical apprenticeship and certification authorities','https://red-seal.ca/eng/trades/const-elect.shtml','profile_ready','2026-08-09',now())
