insert into public.country_occupation_metric_snapshots (profile_key,as_of_date,employment_total,median_weekly_earnings,median_hourly_earnings,annualised_median_salary,all_occupations_median_weekly,part_time_share_pct,female_share_pct,median_age,average_full_time_hours,vacancies_three_month_avg,vacancy_period,vacancy_yoy_pct,employment_growth_5y_pct,employment_growth_10y_pct,shortage_component,vacancy_intensity_component,employer_diversity_component,vacancy_trend_component,entry_level_component,salary_component,growth_component,visa_component,entry_burden_component,opportunity_score,score_methodology_version,score_status,score_evidence,source_checked_at)
values ('CA:electrician','2025-11-19',119300,null,35.00,null,null,null,null,null,null,null,null,null,null,null,15,0,0,0,15,8,0,10,2,50,'career-opportunity-ca-v1','provisional',jsonb_build_object('classification_scope','Exact NOC 2021 unit group 72200 Electricians (except industrial and power system).','labour_scope','COPS reports about 119,300 workers in 2023; Job Bank national median wage is CAD 35.00/hour.','shortage_note','COPS classifies NOC 72200 as MODERATE RISK OF SHORTAGE nationally for 2024-2033.','visa_basis','NOC 72200 is in the current Express Entry trade occupations category.','entry_level_basis','Construction Electrician is a Red Seal trade with a structured apprenticeship route.','entry_burden_basis','Electrical certification/licensing is jurisdictional and regulated; burden receives 2/5 rather than an unregulated-trade score.','salary_method','Exact CAD 35.00/hour earns 8/10 under Canada v1 wage bands.','vacancy_scope','Point-in-time Job Bank posting counts are not scored as a three-month vacancy series.','program_gap','courses_ca currently has no verified electrician programme record, so no programme link is fabricated.'),'2026-08-09')
